//! Line framing and response rendering (SPEC.md section 1).

use std::io::{self, BufRead, Write};

use serde_json::{json, Map, Value};

use crate::{Error, ErrorCode};

/// Reads commands line by line from `input` and writes one response line per
/// command to `output`, flushing each response before reading the next line.
///
/// Returns `Ok(())` at end of input. Errors are only I/O failures; a bad
/// command gets an `ok: false` response instead.
pub fn serve<R: BufRead, W: Write>(mut input: R, mut output: W) -> io::Result<()> {
    let mut line = Vec::new();
    loop {
        line.clear();
        if input.read_until(b'\n', &mut line)? == 0 {
            return Ok(());
        }
        if line.last() == Some(&b'\n') {
            line.pop();
        }
        let response = render(handle_line(&line));
        serde_json::to_writer(&mut output, &response)?;
        output.write_all(b"\n")?;
        output.flush()?;
    }
}

fn handle_line(line: &[u8]) -> Result<Value, Error> {
    let text = std::str::from_utf8(line)
        .map_err(|_| Error::new(ErrorCode::InvalidRequest, "line is not valid UTF-8"))?;
    let value: Value = serde_json::from_str(text)
        .map_err(|err| Error::new(ErrorCode::InvalidRequest, format!("line is not JSON: {err}")))?;
    let Value::Object(object) = value else {
        return Err(Error::new(ErrorCode::InvalidRequest, "line is not a JSON object"));
    };
    let Some(Value::String(command)) = object.get("Command") else {
        return Err(Error::new(ErrorCode::InvalidRequest, "missing string Command member"));
    };
    Err(Error::new(
        ErrorCode::InvalidRequest,
        format!("unknown command {command}"),
    ))
}

fn render(outcome: Result<Value, Error>) -> Value {
    match outcome {
        Ok(value) => {
            let mut members = Map::new();
            members.insert("ok".to_owned(), Value::Bool(true));
            if let Value::Object(result) = value {
                members.extend(result);
            }
            Value::Object(members)
        }
        Err(error) => json!({
            "ok": false,
            "error": {"code": error.code.as_str(), "message": error.message},
        }),
    }
}

