mod common;

use common::run;
use serde_json::{json, Value};

/// Runs `lines` as one session and returns the responses.
fn session(lines: &[&str]) -> Vec<Value> {
    run(&lines.join("\n"))
}

/// Runs `lines` and returns the response to the last one.
fn last(lines: &[&str]) -> Value {
    session(lines).pop().expect("at least one response")
}

fn assert_ok(response: &Value) {
    assert_eq!(response, &json!({"ok": true}), "expected success");
}

fn assert_error(response: &Value, code: &str) {
    assert_eq!(response["ok"], false, "expected failure, got {response}");
    assert_eq!(response["error"]["code"], code, "wrong error in {response}");
}

