//! A single queue: its configuration and its messages, with the rules for
//! sending, receiving and expiring them (SPEC.md sections 4 and 6).

use std::collections::{BTreeMap, HashMap, HashSet};

use crate::attributes::{AttributeChanges, Attributes, DeadLetter};
use crate::command::SendRequest;
use crate::{Error, ErrorCode};

/// The most messages one queue holds, counting every state.
pub const MAX_MESSAGES: usize = 100_000;

/// Seconds after an accepted FIFO send during which the same deduplication id
/// counts as a duplicate.
const DEDUPLICATION_WINDOW: u64 = 300;

/// Message counts by state at one instant.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub struct Counts {
    pub visible: usize,
    pub in_flight: usize,
    pub delayed: usize,
}

/// The state of a message at one instant. A message is delayed, else in
/// flight, else visible.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum State {
    Delayed,
    InFlight,
    Visible,
}

#[derive(Debug)]
struct Message {
    id: u64,
    body: String,
    group_id: Option<String>,
    sequence_number: Option<u64>,
    sent_at: u64,
    receive_count: u32,
    first_received_at: Option<u64>,
    /// Delayed while `now < delayed_until`.
    delayed_until: u64,
    /// In flight while `now < in_flight_until`.
    in_flight_until: u64,
}

impl Message {
    fn state(&self, now: u64) -> State {
        if now < self.delayed_until {
            State::Delayed
        } else if now < self.in_flight_until {
            State::InFlight
        } else {
            State::Visible
        }
    }
}

/// The record a FIFO send leaves, used to recognise duplicates.
#[derive(Debug)]
struct Accepted {
    at: u64,
    message_id: u64,
    sequence_number: u64,
}

/// A message as handed to a client by ReceiveMessage.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Delivery {
    pub message_id: u64,
    pub receipt: u64,
    pub body: String,
    pub receive_count: u32,
    pub sent_at: u64,
    pub first_received_at: u64,
    pub group_id: Option<String>,
    pub sequence_number: Option<u64>,
}

#[derive(Debug)]
pub struct Queue {
    attributes: Attributes,
    /// Keyed by arrival order: the order in which messages joined this queue.
    /// Keys are never reused, so the order of the map is the order of arrival.
    messages: BTreeMap<u64, Message>,
    next_arrival: u64,
    next_sequence: u64,
    deduplication: HashMap<String, Accepted>,
    /// The clock value at which expiry last ran; `None` after the retention
    /// period may have changed.
    expired_at: Option<u64>,
}

impl Queue {
    pub fn new(attributes: Attributes) -> Self {
        Queue {
            attributes,
            messages: BTreeMap::new(),
            next_arrival: 0,
            next_sequence: 1,
            deduplication: HashMap::new(),
            expired_at: None,
        }
    }

    pub fn attributes(&self) -> &Attributes {
        &self.attributes
    }

    pub fn reconfigure(&mut self, changes: &AttributeChanges, dead_letter: Option<DeadLetter>) {
        self.attributes.apply(changes, dead_letter);
        self.expired_at = None;
    }

    /// Clears the dead-letter configuration if it points at `queue`, which is
    /// being deleted.
    pub fn detach_dead_letter(&mut self, queue: &str) {
        if self
            .attributes
            .dead_letter
            .as_ref()
            .is_some_and(|dead_letter| dead_letter.queue == queue)
        {
            self.attributes.dead_letter = None;
        }
    }

    /// Removes every message whose retention period has ended by `now`.
    ///
    /// Runs at most once per clock value: the clock only moves forward, and a
    /// retention change resets `expired_at`. This keeps long runs of sends at
    /// one instant from rescanning the queue each time.
    pub fn expire(&mut self, now: u64) {
        if self.expired_at == Some(now) {
            return;
        }
        let retention = u64::from(self.attributes.retention_seconds);
        self.messages
            .retain(|_, message| now < message.sent_at.saturating_add(retention));
        self.expired_at = Some(now);
    }

    pub fn counts(&self, now: u64) -> Counts {
        let mut counts = Counts::default();
        for message in self.messages.values() {
            match message.state(now) {
                State::Delayed => counts.delayed += 1,
                State::InFlight => counts.in_flight += 1,
                State::Visible => counts.visible += 1,
            }
        }
        counts
    }

    pub fn purge(&mut self) {
        // Sequence numbers and deduplication records outlive the messages.
        self.messages.clear();
    }

    /// The rules of SendMessage that depend on the queue's type (section 6,
    /// rules 1 to 3).
    pub fn check_send(&self, request: &SendRequest) -> Result<(), Error> {
        if !self.attributes.fifo {
            if request.group_id.is_some() || request.deduplication_id.is_some() {
                return Err(Error::new(
                    ErrorCode::UnsupportedOperation,
                    "GroupId and DeduplicationId are only allowed on a FIFO queue",
                ));
            }
            return Ok(());
        }
        if request.delay_seconds.is_some() {
            return Err(Error::new(
                ErrorCode::UnsupportedOperation,
                "DelaySeconds is not allowed on a FIFO queue",
            ));
        }
        if request.group_id.is_none() {
            return Err(Error::new(
                ErrorCode::MissingParameter,
                "GroupId is required on a FIFO queue",
            ));
        }
        if request.deduplication_id.is_none() && !self.attributes.content_based_deduplication {
            return Err(Error::new(
                ErrorCode::MissingParameter,
                "DeduplicationId is required when ContentBasedDeduplication is false",
            ));
        }
        Ok(())
    }

    /// The earlier FIFO send that makes `request` a duplicate, if any.
    pub fn duplicate_of(&self, now: u64, request: &SendRequest) -> Option<(u64, u64)> {
        if !self.attributes.fifo {
            return None;
        }
        self.deduplication
            .get(deduplication_id(request))
            .filter(|accepted| now < accepted.at.saturating_add(DEDUPLICATION_WINDOW))
            .map(|accepted| (accepted.message_id, accepted.sequence_number))
    }

    /// Rule 5 of SendMessage: the queue must have room for one more message.
    pub fn check_capacity(&self) -> Result<(), Error> {
        if self.messages.len() >= MAX_MESSAGES {
            return Err(Error::new(
                ErrorCode::LimitExceeded,
                format!("a queue holds at most {MAX_MESSAGES} messages"),
            ));
        }
        Ok(())
    }

    /// Adds an accepted message at the end of the queue. Returns its sequence
    /// number on a FIFO queue.
    pub fn push(&mut self, now: u64, message_id: u64, request: SendRequest) -> Option<u64> {
        let delay = request.delay_seconds.unwrap_or(self.attributes.delay_seconds);
        let sequence_number = if self.attributes.fifo {
            let number = self.next_sequence;
            self.next_sequence += 1;
            self.deduplication.insert(
                deduplication_id(&request).to_owned(),
                Accepted {
                    at: now,
                    message_id,
                    sequence_number: number,
                },
            );
            Some(number)
        } else {
            None
        };
        let arrival = self.next_arrival;
        self.next_arrival += 1;
        self.messages.insert(
            arrival,
            Message {
                id: message_id,
                body: request.body,
                group_id: request.group_id,
                sequence_number,
                sent_at: now,
                receive_count: 0,
                first_received_at: None,
                delayed_until: now.saturating_add(u64::from(delay)),
                in_flight_until: 0,
            },
        );
        sequence_number
    }

    /// Delivers up to `max` eligible messages in arrival order (section 6,
    /// ReceiveMessage). Each delivery takes the next receipt number from
    /// `next_receipt`.
    pub fn receive(
        &mut self,
        now: u64,
        max: u32,
        visibility_timeout: u32,
        next_receipt: &mut u64,
    ) -> Vec<Delivery> {
        let keys = self.eligible(now, max as usize);
        let mut deliveries = Vec::with_capacity(keys.len());
        for key in keys {
            let receipt = *next_receipt;
            *next_receipt += 1;
            // Keys come from `eligible`, which only reads the map.
            let message = self
                .messages
                .get_mut(&key)
                .expect("eligible keys name messages in the queue");
            message.receive_count += 1;
            let first_received_at = *message.first_received_at.get_or_insert(now);
            message.in_flight_until = now.saturating_add(u64::from(visibility_timeout));
            deliveries.push(Delivery {
                message_id: message.id,
                receipt,
                body: message.body.clone(),
                receive_count: message.receive_count,
                sent_at: message.sent_at,
                first_received_at,
                group_id: message.group_id.clone(),
                sequence_number: message.sequence_number,
            });
        }
        deliveries
    }

    /// The arrival keys of the messages a receive at `now` delivers, at most `max`.
    ///
    /// A message is eligible if it is visible and, on a FIFO queue, no earlier
    /// message of its group is still in the queue. Every message that stays in
    /// the queue blocks its group for the rest of the scan, whatever its state.
    fn eligible(&self, now: u64, max: usize) -> Vec<u64> {
        let mut blocked_groups: HashSet<&str> = HashSet::new();
        let mut keys = Vec::new();
        for (&key, message) in &self.messages {
            if keys.len() == max {
                break;
            }
            let group = message.group_id.as_deref();
            if group.is_some_and(|group| blocked_groups.contains(group)) {
                continue;
            }
            if let Some(group) = group {
                blocked_groups.insert(group);
            }
            if message.state(now) == State::Visible {
                keys.push(key);
            }
        }
        keys
    }
}

/// The deduplication id of a FIFO send: its own id, or the body when the
/// queue derives ids from content.
fn deduplication_id(request: &SendRequest) -> &str {
    request.deduplication_id.as_deref().unwrap_or(&request.body)
}

/// Whether a queue name is valid. Names are checked by CreateQueue only; other
/// commands look names up as given.
pub fn is_fifo_name(name: &str) -> bool {
    name.ends_with(".fifo")
}

