    assert_eq!(responses[2], json!({"ok": true, "MessageId": "m-1", "SequenceNumber": 1}));
    assert_eq!(responses[3], json!({"ok": true, "MessageId": "m-2", "SequenceNumber": 2}));
}

#[test]
fn duplicate_within_the_window_returns_the_original_and_changes_nothing() {
    let responses = session(&[
