        FIFO,
        r#"{"Command": "SendMessage", "QueueName": "f.fifo", "Body": "a", "GroupId": "g", "DeduplicationId": "d1"}"#,
        &tick(200),
        r#"{"Command": "SendMessage", "QueueName": "f.fifo", "Body": "a", "GroupId": "g", "DeduplicationId": "d1"}"#,
        &tick(100),
        r#"{"Command": "SendMessage", "QueueName": "f.fifo", "Body": "a", "GroupId": "g", "DeduplicationId": "d1"}"#,
    ]);

    assert_eq!(responses[1], json!({"ok": true, "MessageId": "m-1", "SequenceNumber": 1}));
    assert_eq!(responses[3], json!({"ok": true, "MessageId": "m-1", "SequenceNumber": 1}));
    assert_eq!(responses[5], json!({"ok": true, "MessageId": "m-2", "SequenceNumber": 2}));
