        r#"{"Command": "SendMessage", "QueueName": "other.fifo", "Body": "a", "GroupId": "g1", "DeduplicationId": "d"}"#,
    ]);

    assert_eq!(responses[3], json!({"ok": true, "MessageId": "m-1", "SequenceNumber": 1}));
