        STANDARD,
        &send("jobs", "a"),
        r#"{"Command": "ReceiveMessage", "QueueName": "jobs", "VisibilityTimeout": 0}"#,
        &receive("jobs"),
    ]);

    assert_eq!(responses[3]["Messages"][0]["ReceiptHandle"], "r-2");
    assert_eq!(responses[3]["Messages"][0]["ReceiveCount"], 2);
}

