fn redelivery_keeps_arrival_order() {
    let responses = session(&[
        STANDARD,
        &send("jobs", "first"),
        &send("jobs", "second"),
        &receive("jobs"),
        &receive("jobs"),
        &tick(30),
        &receive("jobs"),
