//! The state of the service and the meaning of each command (SPEC.md sections 3 to 6).

use std::collections::BTreeMap;

use crate::attributes::{AttributeChanges, Attributes};
use crate::command::{Command, ReceiveRequest, SendRequest};
use crate::queue::{Counts, Delivery, Queue};
use crate::{Error, ErrorCode};

const MAX_QUEUES: usize = 1000;

/// What a successful command returns, before it is rendered as JSON.
#[derive(Debug, PartialEq, Eq)]
pub enum Reply {
    Empty,
    QueueAttributes {
        attributes: Attributes,
        counts: Counts,
    },
    QueueNames(Vec<String>),
    Now(u64),
    Sent {
        message_id: u64,
        sequence_number: Option<u64>,
    },
    Received(Vec<Delivery>),
}

#[derive(Debug)]
pub struct Broker {
    now: u64,
    /// Ordered by name, so listings come out in byte order.
    queues: BTreeMap<String, Queue>,
    /// The next `MessageId` number to hand out; numbers are not reused.
    next_message_id: u64,
    /// The next `ReceiptHandle` number to hand out; numbers are not reused.
    next_receipt: u64,
}

impl Broker {
    pub fn new() -> Self {
        Broker {
            now: 0,
            queues: BTreeMap::new(),
            next_message_id: 1,
            next_receipt: 1,
        }
    }

    pub fn execute(&mut self, command: Command) -> Result<Reply, Error> {
        match command {
            Command::CreateQueue { name, attributes } => self.create_queue(&name, &attributes),
            Command::SetQueueAttributes { name, changes } => {
                self.set_queue_attributes(&name, &changes)
            }
            Command::GetQueueAttributes { name } => self.get_queue_attributes(&name),
            Command::ListQueues { prefix } => Ok(self.list_queues(prefix.as_deref().unwrap_or(""))),
            Command::DeleteQueue { name } => self.delete_queue(&name),
            Command::PurgeQueue { name } => self.purge_queue(&name),
            Command::Tick { seconds } => {
                self.now = self.now.saturating_add(u64::from(seconds));
                Ok(Reply::Now(self.now))
            }
            Command::SendMessage(request) => self.send_message(request),
            Command::ReceiveMessage(request) => self.receive_message(&request),
        }
    }

    fn create_queue(&mut self, name: &str, changes: &AttributeChanges) -> Result<Reply, Error> {
        let fifo = changes.fifo.unwrap_or(false);
        let content_based = changes.content_based_deduplication.unwrap_or(false);
        if is_fifo_name(name) != fifo {
            return Err(Error::new(
                ErrorCode::QueueNameInvalid,
                "a queue name ends in .fifo exactly when the queue is FIFO",
            ));
        }
        if content_based && !fifo {
            return Err(invalid_value(
                "ContentBasedDeduplication is only allowed on a FIFO queue",
            ));
        }
        let dead_letter = changes.dead_letter()?;
        let mut wanted = Attributes::default();
        wanted.apply(changes, dead_letter);

        if let Some(existing) = self.queues.get(name) {
            return if existing.attributes() == &wanted {
                Ok(Reply::Empty)
            } else {
                Err(Error::new(
                    ErrorCode::QueueAlreadyExists,
                    format!("queue {name} exists with different attributes"),
                ))
            };
        }
        if let Some(dead_letter) = &wanted.dead_letter {
            let target = self.existing(&dead_letter.queue)?;
            if target.attributes().fifo != fifo {
                return Err(invalid_value(
                    "the dead-letter queue must have the same FIFO type as this queue",
                ));
            }
        }
        if self.queues.len() >= MAX_QUEUES {
            return Err(Error::new(
                ErrorCode::LimitExceeded,
                format!("at most {MAX_QUEUES} queues can exist"),
            ));
        }
        self.queues.insert(name.to_owned(), Queue::new(wanted));
        Ok(Reply::Empty)
    }

    fn set_queue_attributes(&mut self, name: &str, changes: &AttributeChanges) -> Result<Reply, Error> {
        let fifo = self.existing(name)?.attributes().fifo;
        if changes.fifo.is_some() {
            return Err(Error::new(
                ErrorCode::UnsupportedOperation,
                "the FIFO type of a queue cannot be changed",
            ));
        }
        if changes.content_based_deduplication == Some(true) && !fifo {
            return Err(invalid_value(
                "ContentBasedDeduplication is only allowed on a FIFO queue",
            ));
        }
        let dead_letter = changes.dead_letter()?;
        if let Some(dead_letter) = &dead_letter {
            if dead_letter.queue == name {
                return Err(invalid_value("a queue cannot be its own dead-letter queue"));
            }
            let target = self.existing(&dead_letter.queue)?;
            if target.attributes().fifo != fifo {
                return Err(invalid_value(
                    "the dead-letter queue must have the same FIFO type as this queue",
                ));
            }
        }
        // Expire under the old retention first: a retention change applies to
        // messages from this moment on, and cannot revive removed ones.
        live_queue(&mut self.queues, name, self.now)?.reconfigure(changes, dead_letter);
        Ok(Reply::Empty)
    }

    fn get_queue_attributes(&mut self, name: &str) -> Result<Reply, Error> {
        let queue = live_queue(&mut self.queues, name, self.now)?;
        Ok(Reply::QueueAttributes {
            attributes: queue.attributes().clone(),
            counts: queue.counts(self.now),
        })
    }

    fn list_queues(&self, prefix: &str) -> Reply {
        Reply::QueueNames(
            self.queues
                .keys()
                .filter(|name| name.starts_with(prefix))
                .cloned()
                .collect(),
        )
    }

    fn delete_queue(&mut self, name: &str) -> Result<Reply, Error> {
        self.existing(name)?;
        self.queues.remove(name);
        for queue in self.queues.values_mut() {
            queue.detach_dead_letter(name);
        }
        Ok(Reply::Empty)
    }

    fn purge_queue(&mut self, name: &str) -> Result<Reply, Error> {
        live_queue(&mut self.queues, name, self.now)?.purge();
        Ok(Reply::Empty)
    }

    fn send_message(&mut self, request: SendRequest) -> Result<Reply, Error> {
        let now = self.now;
        let queue = live_queue(&mut self.queues, &request.queue, now)?;
        queue.check_send(&request)?;
        if let Some((message_id, sequence_number)) = queue.duplicate_of(now, &request) {
            return Ok(Reply::Sent {
                message_id,
                sequence_number: Some(sequence_number),
            });
        }
        queue.check_capacity()?;
        let message_id = self.next_message_id;
        self.next_message_id += 1;
        let sequence_number = queue.push(now, message_id, request);
        Ok(Reply::Sent {
            message_id,
            sequence_number,
        })
    }

    fn receive_message(&mut self, request: &ReceiveRequest) -> Result<Reply, Error> {
        let now = self.now;
        let queue = live_queue(&mut self.queues, &request.queue, now)?;
        let visibility_timeout = request
            .visibility_timeout
            .unwrap_or(queue.attributes().visibility_timeout);
        let deliveries = queue.receive(
            now,
            request.max_messages,
            visibility_timeout,
            &mut self.next_receipt,
        );
        Ok(Reply::Received(deliveries))
    }

    fn existing(&self, name: &str) -> Result<&Queue, Error> {
        self.queues.get(name).ok_or_else(|| does_not_exist(name))
    }

    fn existing_mut(&mut self, name: &str) -> Result<&mut Queue, Error> {
        self.queues.get_mut(name).ok_or_else(|| does_not_exist(name))
    }
}

/// The named queue, with messages that have expired by `now` removed.
fn live_queue<'a>(
    queues: &'a mut BTreeMap<String, Queue>,
    name: &str,
    now: u64,
) -> Result<&'a mut Queue, Error> {
    let queue = queues.get_mut(name).ok_or_else(|| does_not_exist(name))?;
    queue.expire(now);
    Ok(queue)
}

fn does_not_exist(name: &str) -> Error {
    Error::new(
        ErrorCode::QueueDoesNotExist,
        format!("queue {name} does not exist"),
    )
}

fn is_fifo_name(name: &str) -> bool {
    name.ends_with(".fifo")
}

fn invalid_value(message: &str) -> Error {
    Error::new(ErrorCode::InvalidParameterValue, message)
}

mod common;

use common::{assert_error, assert_ok, last, session};
use serde_json::{json, Value};

#[test]
fn create_queue_with_defaults_succeeds_with_no_result_members() {
    let response = last(&[r#"{"Command": "CreateQueue", "QueueName": "jobs"}"#]);

    assert_eq!(response, json!({"ok": true}));
}

#[test]
fn creating_an_existing_queue_with_the_same_attributes_changes_nothing() {
    let responses = session(&[
        r#"{"Command": "CreateQueue", "QueueName": "jobs"}"#,
        r#"{"Command": "CreateQueue", "QueueName": "jobs", "Attributes": {"VisibilityTimeout": 30}}"#,
    ]);

    assert_ok(&responses[1]);
}

#[test]
fn creating_an_existing_queue_with_other_attributes_fails() {
    let responses = session(&[
        r#"{"Command": "CreateQueue", "QueueName": "jobs"}"#,
        r#"{"Command": "CreateQueue", "QueueName": "jobs", "Attributes": {"DelaySeconds": 5}}"#,
    ]);

    assert_error(&responses[1], "QueueAlreadyExists");
}

#[test]
fn queue_name_rules_decide_validity() {
    let long = "a".repeat(80);
    let too_long = "a".repeat(81);
    let fifo_max = format!("{}.fifo", "a".repeat(75));
    let fifo_too_long = format!("{}.fifo", "a".repeat(76));
    let cases: Vec<(String, bool, Option<&str>)> = vec![
        ("a".to_owned(), false, None),
        ("A-z_09".to_owned(), false, None),
        (long, false, None),
        (too_long, false, Some("QueueNameInvalid")),
        ("".to_owned(), false, Some("QueueNameInvalid")),
        ("a.b".to_owned(), false, Some("QueueNameInvalid")),
        ("a b".to_owned(), false, Some("QueueNameInvalid")),
        ("é".to_owned(), false, Some("QueueNameInvalid")),
        ("jobs.fifo".to_owned(), false, Some("QueueNameInvalid")),
        ("jobs".to_owned(), true, Some("QueueNameInvalid")),
        ("jobs.fifo".to_owned(), true, None),
        (fifo_max, true, None),
        (fifo_too_long, true, Some("QueueNameInvalid")),
    ];

    for (name, fifo, expected) in cases {
        let line = format!(
            r#"{{"Command": "CreateQueue", "QueueName": {}, "Attributes": {{"Fifo": {fifo}}}}}"#,
            serde_json::to_string(&name).unwrap()
        );
        let response = last(&[&line]);
        match expected {
            None => assert_ok(&response),
            Some(code) => assert_error(&response, code),
        }
    }
}

#[test]
fn queue_name_is_checked_before_attributes() {
    let response = last(&[
        r#"{"Command": "CreateQueue", "QueueName": "bad name", "Attributes": {"VisibilityTimeout": 99999}}"#,
    ]);

    assert_error(&response, "QueueNameInvalid");
}

#[test]
fn missing_queue_name_is_reported_before_bad_attributes() {
    let response = last(&[r#"{"Command": "CreateQueue", "Attributes": {"VisibilityTimeout": "x"}}"#]);

    assert_error(&response, "MissingParameter");
}

#[test]
fn non_string_queue_name_is_an_invalid_parameter_value() {
    let response = last(&[r#"{"Command": "CreateQueue", "QueueName": 5}"#]);

    assert_error(&response, "InvalidParameterValue");
}

#[test]
fn attribute_values_are_checked_by_type_and_range() {
    let cases = [
        (r#"{"VisibilityTimeout": 43200}"#, true),
        (r#"{"VisibilityTimeout": 43201}"#, false),
        (r#"{"VisibilityTimeout": "30"}"#, false),
        (r#"{"VisibilityTimeout": 30.0}"#, false),
        (r#"{"VisibilityTimeout": 3e1}"#, false),
        (r#"{"VisibilityTimeout": -1}"#, false),
        (r#"{"DelaySeconds": 900}"#, true),
        (r#"{"DelaySeconds": 901}"#, false),
        (r#"{"RetentionSeconds": 59}"#, false),
        (r#"{"RetentionSeconds": 60}"#, true),
        (r#"{"RetentionSeconds": 1209600}"#, true),
        (r#"{"RetentionSeconds": 1209601}"#, false),
        (r#"{"Fifo": "true"}"#, false),
        (r#"{"ContentBasedDeduplication": 1}"#, false),
        (r#"{"Color": 1}"#, false),
        (r#"{"VisibilityTimeout": null}"#, true),
        (r#"{"DelaySeconds": null, "VisibilityTimeout": 1}"#, true),
    ];

    for (attributes, valid) in cases {
        let line = format!(
            r#"{{"Command": "CreateQueue", "QueueName": "q-{}", "Attributes": {attributes}}}"#,
            attributes.len()
        );
        let response = last(&[&line]);
        if valid {
            assert_ok(&response);
        } else {
            assert_error(&response, "InvalidParameterValue");
        }
    }
}

#[test]
fn attributes_must_be_an_object() {
    let responses = session(&[
        r#"{"Command": "CreateQueue", "QueueName": "a", "Attributes": []}"#,
        r#"{"Command": "CreateQueue", "QueueName": "b", "Attributes": "x"}"#,
        r#"{"Command": "CreateQueue", "QueueName": "c", "Attributes": null}"#,
    ]);

    assert_error(&responses[0], "InvalidParameterValue");
    assert_error(&responses[1], "InvalidParameterValue");
    assert_ok(&responses[2]);
}

#[test]
fn content_based_deduplication_requires_a_fifo_queue() {
    let responses = session(&[
        r#"{"Command": "CreateQueue", "QueueName": "std", "Attributes": {"ContentBasedDeduplication": true}}"#,
        r#"{"Command": "CreateQueue", "QueueName": "std2", "Attributes": {"ContentBasedDeduplication": false}}"#,
        r#"{"Command": "CreateQueue", "QueueName": "f.fifo", "Attributes": {"Fifo": true, "ContentBasedDeduplication": true}}"#,
    ]);

    assert_error(&responses[0], "InvalidParameterValue");
    assert_ok(&responses[1]);
    assert_ok(&responses[2]);
}

#[test]
fn dead_letter_members_must_be_given_together() {
    let responses = session(&[
        r#"{"Command": "CreateQueue", "QueueName": "dlq"}"#,
        r#"{"Command": "CreateQueue", "QueueName": "a", "Attributes": {"DeadLetterQueue": "dlq"}}"#,
        r#"{"Command": "CreateQueue", "QueueName": "b", "Attributes": {"MaxReceiveCount": 3}}"#,
    ]);

    assert_error(&responses[1], "InvalidParameterValue");
    assert_error(&responses[2], "InvalidParameterValue");
}

#[test]
fn max_receive_count_is_checked_by_range() {
    let responses = session(&[
        r#"{"Command": "CreateQueue", "QueueName": "dlq"}"#,
        r#"{"Command": "CreateQueue", "QueueName": "a", "Attributes": {"DeadLetterQueue": "dlq", "MaxReceiveCount": 0}}"#,
        r#"{"Command": "CreateQueue", "QueueName": "b", "Attributes": {"DeadLetterQueue": "dlq", "MaxReceiveCount": 1001}}"#,
        r#"{"Command": "CreateQueue", "QueueName": "c", "Attributes": {"DeadLetterQueue": "dlq", "MaxReceiveCount": 1000}}"#,
    ]);

    assert_error(&responses[1], "InvalidParameterValue");
    assert_error(&responses[2], "InvalidParameterValue");
    assert_ok(&responses[3]);
}

#[test]
fn dead_letter_queue_must_exist() {
    let response = last(&[
        r#"{"Command": "CreateQueue", "QueueName": "a", "Attributes": {"DeadLetterQueue": "nope", "MaxReceiveCount": 3}}"#,
    ]);

    assert_error(&response, "QueueDoesNotExist");
}

#[test]
fn dead_letter_queue_must_have_the_same_fifo_type() {
    let response = last(&[
        r#"{"Command": "CreateQueue", "QueueName": "dlq"}"#,
        r#"{"Command": "CreateQueue", "QueueName": "f.fifo", "Attributes": {"Fifo": true, "DeadLetterQueue": "dlq", "MaxReceiveCount": 3}}"#,
    ]);

    assert_error(&response, "InvalidParameterValue");
}

#[test]
fn a_queue_cannot_be_its_own_dead_letter_queue_on_create() {
    let response = last(&[
        r#"{"Command": "CreateQueue", "QueueName": "a", "Attributes": {"DeadLetterQueue": "a", "MaxReceiveCount": 3}}"#,
    ]);

    assert_error(&response, "QueueDoesNotExist");
}

#[test]
fn queue_count_is_limited_to_1000() {
    let mut lines: Vec<String> = (0..1000)
        .map(|n| format!(r#"{{"Command": "CreateQueue", "QueueName": "q{n}"}}"#))
        .collect();
    lines.push(r#"{"Command": "CreateQueue", "QueueName": "one-too-many"}"#.to_owned());
    let input = lines.join("\n");

    let responses = run(&input);

