/// followed by `.fifo`.
fn is_valid_queue_name(name: &str) -> bool {
    let (base, max_len) = match name.strip_suffix(".fifo") {
        Some(base) => (base, 75),
        None => (name, 80),
    };
    (1..=max_len).contains(&base.len())
        && base
            .bytes()
            .all(|byte| byte.is_ascii_alphanumeric() || byte == b'_' || byte == b'-')
}

