/// Runs ReceiveMessage (section 6): delivers up to `max` eligible messages
/// in arrival order, and moves messages that have used up their receives
/// out of this queue. Each delivery takes the next receipt number from
/// `next_receipt`; the moved messages are returned for the dead-letter
/// queue to accept.
pub fn receive(
    &mut self,
    now: u64,
    max: u32,
    visibility_timeout: u32,
    next_receipt: &mut u64,
) -> ReceiveOutcome {
    let steps = self.plan_receive(now, max as usize);
    let mut outcome = ReceiveOutcome::default();
    for step in steps {
        match step {
            Step::DeadLetter(key) => {
                let message = self
                    .messages
                    .remove(&key)
                    .expect("planned keys name messages in the queue");
                outcome.dead_letters.push(message);
            }
            Step::Deliver(key) => {
                let receipt = *next_receipt;
                *next_receipt += 1;
                let message = self
                    .messages
                    .get_mut(&key)
                    .expect("planned keys name messages in the queue");
                message.receive_count += 1;
                let first_received_at = *message.first_received_at.get_or_insert(now);
                message.in_flight_until = now.saturating_add(u64::from(visibility_timeout));
                message.latest_receipt = Some(receipt);
                self.receipts.insert(receipt, key);
                outcome.deliveries.push(Delivery {
                    message_id: message.id,
                    receipt,
                    body: message.body.clone(),
                    receive_count: message.receive_count,
                    sent_at: message.sent_at,
                    first_received_at,
                    group_id: message.group_id.clone(),
                    sequence_number: message.sequence_number,
                });
            }
        }
    }
    outcome
}

/// Adds a message moved from a source queue to the end of this queue, which
/// is its dead-letter queue. It keeps its id, body, sent time and group, and
/// starts again: no receives, visible at once, no receipt. A FIFO queue gives
/// it the next sequence number, and a message already past this queue's
/// retention is dropped on arrival.
pub fn accept_dead_letter(&mut self, now: u64, mut message: Message) {
    let sequence_number = self.attributes.fifo.then(|| self.take_sequence());
    if expired(now, message.sent_at, self.attributes.retention_seconds) {
        return;
    }
    message.receive_count = 0;
    message.first_received_at = None;
    message.delayed_until = now;
    message.in_flight_until = 0;
    message.latest_receipt = None;
    message.sequence_number = sequence_number;
    let arrival = self.next_arrival;
    self.next_arrival += 1;
    self.messages.insert(arrival, message);
}

fn take_sequence(&mut self) -> u64 {
    let number = self.next_sequence;
    self.next_sequence += 1;
    number
}

