    /// The steps a receive at `now` takes, in arrival order.
    ///
    /// A message is eligible if it is visible and, on a FIFO queue, no earlier
    /// message of its group is still in the queue. A message that stays in the
    /// queue blocks its group for the rest of the scan, whatever its state. An
    /// eligible message whose receives are used up is moved to the dead-letter
    /// queue instead of delivered: it leaves the queue, so it blocks nothing,
    /// and it does not count toward `max`.
    fn plan_receive(&self, now: u64, max: usize) -> Vec<Step> {
        let max_receive_count = self
            .attributes
            .dead_letter
            .as_ref()
            .map(|dead_letter| dead_letter.max_receive_count);
        let mut blocked_groups: HashSet<&str> = HashSet::new();
        let mut steps = Vec::new();
        let mut delivered = 0;
        for (&key, message) in &self.messages {
            if delivered == max {
                break;
            }
            let group = message.group_id.as_deref();
            if group.is_some_and(|group| blocked_groups.contains(group)) {
                continue;
            }
            if message.state(now) != State::Visible {
                if let Some(group) = group {
                    blocked_groups.insert(group);
                }
                continue;
            }
            if max_receive_count.is_some_and(|limit| message.receive_count >= limit) {
                steps.push(Step::DeadLetter(key));
                continue;
            }
            if let Some(group) = group {
                blocked_groups.insert(group);
            }
            steps.push(Step::Deliver(key));
            delivered += 1;
        }
        steps
    }
}

