        STANDARD,
        &send("jobs", "a"),
        &send("jobs", "b"),
        &receive("jobs"),
        r#"{"Command": "SetQueueAttributes", "QueueName": "jobs", "Attributes": {"DelaySeconds": 10}}"#,
        &send("jobs", "c"),
