1	//! The state of the service and the meaning of each command (SPEC.md sections 3 to 6).
2	
3	use std::collections::BTreeMap;
4	
5	use crate::attributes::{AttributeChanges, Attributes};
6	use crate::command::{Command, ReceiveRequest, SendRequest};
7	use crate::queue::{Counts, Delivery, Queue};
8	use crate::{Error, ErrorCode};
9	
10	const MAX_QUEUES: usize = 1000;
11	
12	/// What a successful command returns, before it is rendered as JSON.
13	#[derive(Debug, PartialEq, Eq)]
14	pub enum Reply {
15	    Empty,
16	    QueueAttributes {
17	        attributes: Attributes,
18	        counts: Counts,
19	    },
20	    QueueNames(Vec<String>),
21	    Now(u64),
22	    Sent {
23	        message_id: u64,
24	        sequence_number: Option<u64>,
25	    },
26	    Received(Vec<Delivery>),
27	}
28	
29	#[derive(Debug)]
30	pub struct Broker {
31	    now: u64,
32	    /// Ordered by name, so listings come out in byte order.
33	    queues: BTreeMap<String, Queue>,
34	    /// The next `MessageId` number to hand out; numbers are not reused.
35	    next_message_id: u64,
36	    /// The next `ReceiptHandle` number to hand out; numbers are not reused.
37	    next_receipt: u64,
38	}
39	
40	impl Broker {
41	    pub fn new() -> Self {
42	        Broker {
43	            now: 0,
44	            queues: BTreeMap::new(),
45	            next_message_id: 1,
46	            next_receipt: 1,
47	        }
48	    }
49	
50	    pub fn execute(&mut self, command: Command) -> Result<Reply, Error> {
51	        match command {
52	            Command::CreateQueue { name, attributes } => self.create_queue(&name, &attributes),
53	            Command::SetQueueAttributes { name, changes } => {
54	                self.set_queue_attributes(&name, &changes)
55	            }
56	            Command::GetQueueAttributes { name } => self.get_queue_attributes(&name),
57	            Command::ListQueues { prefix } => Ok(self.list_queues(prefix.as_deref().unwrap_or(""))),
58	            Command::DeleteQueue { name } => self.delete_queue(&name),
59	            Command::PurgeQueue { name } => self.purge_queue(&name),
60	            Command::Tick { seconds } => {
61	                self.now = self.now.saturating_add(u64::from(seconds));
62	                Ok(Reply::Now(self.now))
63	            }
64	            Command::SendMessage(request) => self.send_message(request),
65	            Command::ReceiveMessage(request) => self.receive_message(&request),
66	            Command::DeleteMessage { queue, receipt } => self.delete_message(&queue, &receipt),
67	            Command::ChangeMessageVisibility {
68	                queue,
69	                receipt,
70	                visibility_timeout,
71	            } => self.change_message_visibility(&queue, &receipt, visibility_timeout),
72	        }
73	    }
74	
75	    fn create_queue(&mut self, name: &str, changes: &AttributeChanges) -> Result<Reply, Error> {
76	        let fifo = changes.fifo.unwrap_or(false);
77	        let content_based = changes.content_based_deduplication.unwrap_or(false);
78	        if is_fifo_name(name) != fifo {
79	            return Err(Error::new(
80	                ErrorCode::QueueNameInvalid,
81	                "a queue name ends in .fifo exactly when the queue is FIFO",
82	            ));
83	        }
84	        if content_based && !fifo {
85	            return Err(invalid_value(
86	                "ContentBasedDeduplication is only allowed on a FIFO queue",
87	            ));
88	        }
89	        let dead_letter = changes.dead_letter()?;
90	        let mut wanted = Attributes::default();
91	        wanted.apply(changes, dead_letter);
92	
93	        if let Some(existing) = self.queues.get(name) {
94	            return if existing.attributes() == &wanted {
95	                Ok(Reply::Empty)
96	            } else {
97	                Err(Error::new(
98	                    ErrorCode::QueueAlreadyExists,
99	                    format!("queue {name} exists with different attributes"),
100	                ))
101	            };
102	        }
103	        if let Some(dead_letter) = &wanted.dead_letter {
104	            let target = self.existing(&dead_letter.queue)?;
105	            if target.attributes().fifo != fifo {
106	                return Err(invalid_value(
107	                    "the dead-letter queue must have the same FIFO type as this queue",
108	                ));
109	            }
110	        }
111	        if self.queues.len() >= MAX_QUEUES {
112	            return Err(Error::new(
113	                ErrorCode::LimitExceeded,
114	                format!("at most {MAX_QUEUES} queues can exist"),
115	            ));
116	        }
117	        self.queues.insert(name.to_owned(), Queue::new(wanted));
118	        Ok(Reply::Empty)
119	    }
120	
121	    fn set_queue_attributes(
122	        &mut self,
123	        name: &str,
124	        changes: &AttributeChanges,
125	    ) -> Result<Reply, Error> {
126	        let fifo = self.existing(name)?.attributes().fifo;
127	        if changes.fifo.is_some() {
128	            return Err(Error::new(
129	                ErrorCode::UnsupportedOperation,
130	                "the FIFO type of a queue cannot be changed",
131	            ));
132	        }
133	        if changes.content_based_deduplication == Some(true) && !fifo {
134	            return Err(invalid_value(
135	                "ContentBasedDeduplication is only allowed on a FIFO queue",
136	            ));
137	        }
138	        let dead_letter = changes.dead_letter()?;
139	        if let Some(dead_letter) = &dead_letter {
140	            if dead_letter.queue == name {
141	                return Err(invalid_value("a queue cannot be its own dead-letter queue"));
142	            }
143	            let target = self.existing(&dead_letter.queue)?;
144	            if target.attributes().fifo != fifo {
145	                return Err(invalid_value(
146	                    "the dead-letter queue must have the same FIFO type as this queue",
147	                ));
148	            }
149	        }
150	        // Expire under the old retention first: a retention change applies to
151	        // messages from this moment on, and cannot revive removed ones.
152	        live_queue(&mut self.queues, name, self.now)?.reconfigure(changes, dead_letter);
153	        Ok(Reply::Empty)
154	    }
155	
156	    fn get_queue_attributes(&mut self, name: &str) -> Result<Reply, Error> {
157	        let queue = live_queue(&mut self.queues, name, self.now)?;
158	        Ok(Reply::QueueAttributes {
159	            attributes: queue.attributes().clone(),
160	            counts: queue.counts(self.now),
161	        })
162	    }
163	
164	    fn list_queues(&self, prefix: &str) -> Reply {
165	        Reply::QueueNames(
166	            self.queues
167	                .keys()
168	                .filter(|name| name.starts_with(prefix))
169	                .cloned()
170	                .collect(),
171	        )
172	    }
173	
174	    fn delete_queue(&mut self, name: &str) -> Result<Reply, Error> {
175	        self.existing(name)?;
176	        self.queues.remove(name);
177	        for queue in self.queues.values_mut() {
178	            queue.detach_dead_letter(name);
179	        }
180	        Ok(Reply::Empty)
181	    }
182	
183	    fn purge_queue(&mut self, name: &str) -> Result<Reply, Error> {
184	        live_queue(&mut self.queues, name, self.now)?.purge();
185	        Ok(Reply::Empty)
186	    }
187	
188	    fn send_message(&mut self, request: SendRequest) -> Result<Reply, Error> {
189	        let now = self.now;
190	        let queue = live_queue(&mut self.queues, &request.queue, now)?;
191	        queue.check_send(&request)?;
192	        if let Some((message_id, sequence_number)) = queue.duplicate_of(now, &request) {
193	            return Ok(Reply::Sent {
194	                message_id,
195	                sequence_number: Some(sequence_number),
196	            });
197	        }
198	        queue.check_capacity()?;
199	        let message_id = self.next_message_id;
200	        self.next_message_id += 1;
201	        let sequence_number = queue.push(now, message_id, request);
202	        Ok(Reply::Sent {
203	            message_id,
204	            sequence_number,
205	        })
206	    }
207	
208	    fn receive_message(&mut self, request: &ReceiveRequest) -> Result<Reply, Error> {
209	        let now = self.now;
210	        let queue = live_queue(&mut self.queues, &request.queue, now)?;
211	        let visibility_timeout = request
212	            .visibility_timeout
213	            .unwrap_or(queue.attributes().visibility_timeout);
214	        let dead_letter_queue = queue
215	            .attributes()
216	            .dead_letter
217	            .as_ref()
218	            .map(|dead_letter| dead_letter.queue.clone());
219	        let outcome = queue.receive(
220	            now,
221	            request.max_messages,
222	            visibility_timeout,
223	            &mut self.next_receipt,
224	        );
225	        if !outcome.dead_letters.is_empty() {
226	            // Only a queue with a dead-letter queue moves messages, and DeleteQueue
227	            // clears every reference to a queue before it goes.
228	            let target = dead_letter_queue
229	                .expect("messages move only from a queue with a dead-letter queue");
230	            let dead_letters = self
231	                .queues
232	                .get_mut(&target)
233	                .expect("a dead-letter reference always names an existing queue");
234	            for message in outcome.dead_letters {
235	                dead_letters.accept_dead_letter(now, message);
236	            }
237	        }
238	        Ok(Reply::Received(outcome.deliveries))
239	    }
240	
241	    fn delete_message(&mut self, name: &str, receipt: &str) -> Result<Reply, Error> {
242	        let now = self.now;
243	        let queue = live_queue(&mut self.queues, name, now)?;
244	        let receipt = parse_issued_receipt(receipt, self.next_receipt)?;
245	        queue.delete_message(now, receipt)?;
246	        Ok(Reply::Empty)
247	    }
248	
249	    fn change_message_visibility(
250	        &mut self,
251	        name: &str,
252	        receipt: &str,
253	        visibility_timeout: u32,
254	    ) -> Result<Reply, Error> {
255	        let now = self.now;
256	        let queue = live_queue(&mut self.queues, name, now)?;
257	        let receipt = parse_issued_receipt(receipt, self.next_receipt)?;
258	        queue.change_visibility(now, receipt, visibility_timeout)?;
259	        Ok(Reply::Empty)
260	    }
261	
262	    fn existing(&self, name: &str) -> Result<&Queue, Error> {
263	        self.queues.get(name).ok_or_else(|| does_not_exist(name))
264	    }
265	}
266	
267	/// The named queue, with messages that have expired by `now` removed.
268	fn live_queue<'a>(
269	    queues: &'a mut BTreeMap<String, Queue>,
270	    name: &str,
271	    now: u64,
272	) -> Result<&'a mut Queue, Error> {
273	    let queue = queues.get_mut(name).ok_or_else(|| does_not_exist(name))?;
274	    queue.advance(now);
275	    Ok(queue)
276	}
277	
278	fn does_not_exist(name: &str) -> Error {
279	    Error::new(
280	        ErrorCode::QueueDoesNotExist,
281	        format!("queue {name} does not exist"),
282	    )
283	}
284	
285	/// The number of a receipt handle this process has issued by `next_receipt`.
286	/// Handles are exact strings: `r-01`, `R-1` and `r-1 ` were never issued.
287	fn parse_issued_receipt(text: &str, next_receipt: u64) -> Result<u64, Error> {
288	    let number = text
289	        .strip_prefix("r-")
290	        .and_then(|digits| digits.parse::<u64>().ok())
291	        .filter(|number| format!("r-{number}") == text);
292	    match number {
293	        Some(number) if (1..next_receipt).contains(&number) => Ok(number),
294	        _ => Err(Error::new(
295	            ErrorCode::ReceiptHandleInvalid,
296	            "the receipt handle was never issued",
297	        )),
298	    }
299	}
300	
301	fn is_fifo_name(name: &str) -> bool {
302	    name.ends_with(".fifo")
303	}
304	
305	fn invalid_value(message: &str) -> Error {
306	    Error::new(ErrorCode::InvalidParameterValue, message)
307	}
