1	//! A single queue: its configuration and its messages, with the rules for
2	//! sending, receiving and expiring them (SPEC.md sections 4 and 6).
3	//!
4	//! Messages live in one map in arrival order. Four indexes sit beside it so
5	//! that no command has to scan the whole queue: one for retention, one for
6	//! messages that are not visible yet, one for what a receive can deliver now,
7	//! and one per FIFO group. Every change to a message updates all the indexes
8	//! it belongs to.
9	
10	use std::collections::{BTreeMap, BTreeSet, HashMap};
11	
12	use crate::attributes::{AttributeChanges, Attributes, DeadLetter};
13	use crate::command::SendRequest;
14	use crate::{Error, ErrorCode};
15	
16	/// The most messages one queue holds, counting every state.
17	pub const MAX_MESSAGES: usize = 100_000;
18	
19	/// Seconds after an accepted FIFO send during which the same deduplication id
20	/// counts as a duplicate.
21	const DEDUPLICATION_WINDOW: u64 = 300;
22	
23	/// Message counts by state at one instant.
24	#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
25	pub struct Counts {
26	    pub visible: usize,
27	    pub in_flight: usize,
28	    pub delayed: usize,
29	}
30	
31	/// The state of a message at one instant.
32	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
33	enum State {
34	    Delayed,
35	    InFlight,
36	    Visible,
37	}
38	
39	#[derive(Debug)]
40	pub struct Message {
41	    id: u64,
42	    body: String,
43	    group_id: Option<String>,
44	    sequence_number: Option<u64>,
45	    sent_at: u64,
46	    receive_count: u32,
47	    first_received_at: Option<u64>,
48	    /// The message is visible from this clock value on. A message that has
49	    /// never been received is delayed until then; one that has is in flight.
50	    visible_at: u64,
51	    /// The receipt of the latest delivery. Only this handle can still act on
52	    /// the message.
53	    latest_receipt: Option<u64>,
54	}
55	
56	impl Message {
57	    fn state(&self, now: u64) -> State {
58	        if now >= self.visible_at {
59	            State::Visible
60	        } else if self.receive_count == 0 {
61	            State::Delayed
62	        } else {
63	            State::InFlight
64	        }
65	    }
66	}
67	
68	/// The record a FIFO send leaves, used to recognise duplicates.
69	#[derive(Debug)]
70	struct Accepted {
71	    at: u64,
72	    message_id: u64,
73	    sequence_number: u64,
74	}
75	
76	/// A message as handed to a client by ReceiveMessage.
77	#[derive(Debug, Clone, PartialEq, Eq)]
78	pub struct Delivery {
79	    pub message_id: u64,
80	    pub receipt: u64,
81	    pub body: String,
82	    pub receive_count: u32,
83	    pub sent_at: u64,
84	    pub first_received_at: u64,
85	    pub group_id: Option<String>,
86	    pub sequence_number: Option<u64>,
87	}
88	
89	/// What one receive did to a queue.
90	#[derive(Debug, Default)]
91	pub struct ReceiveOutcome {
92	    pub deliveries: Vec<Delivery>,
93	    /// Messages moved out of this queue, in the order they were moved.
94	    pub dead_letters: Vec<Message>,
95	}
96	
97	#[derive(Debug)]
98	pub struct Queue {
99	    attributes: Attributes,
100	    /// Keyed by arrival order: the order in which messages joined this queue.
101	    /// Keys are never reused, so map order is arrival order.
102	    messages: BTreeMap<u64, Message>,
103	    /// `(sent_at, arrival)` for every message, so retention can stop at the
104	    /// first message that has not yet expired.
105	    by_sent: BTreeSet<(u64, u64)>,
106	    /// `(visible_at, arrival)` for messages that are not visible yet.
107	    waking: BTreeSet<(u64, u64)>,
108	    /// Arrivals a receive may deliver now: visible messages, and on a FIFO
109	    /// queue only the first message of each group.
110	    ready: BTreeSet<u64>,
111	    /// FIFO only: the arrivals of each group's messages still in the queue.
112	    groups: HashMap<String, BTreeSet<u64>>,
113	    next_arrival: u64,
114	    next_sequence: u64,
115	    deduplication: HashMap<String, Accepted>,
116	    /// Receipt number to the arrival of the message it was issued for. Entries
117	    /// are never removed; a stale one fails the in-flight check.
118	    receipts: HashMap<u64, u64>,
119	}
120	
121	impl Queue {
122	    pub fn new(attributes: Attributes) -> Self {
123	        Queue {
124	            attributes,
125	            messages: BTreeMap::new(),
126	            by_sent: BTreeSet::new(),
127	            waking: BTreeSet::new(),
128	            ready: BTreeSet::new(),
129	            groups: HashMap::new(),
130	            next_arrival: 0,
131	            next_sequence: 1,
132	            deduplication: HashMap::new(),
133	            receipts: HashMap::new(),
134	        }
135	    }
136	
137	    pub fn attributes(&self) -> &Attributes {
138	        &self.attributes
139	    }
140	
141	    pub fn reconfigure(&mut self, changes: &AttributeChanges, dead_letter: Option<DeadLetter>) {
142	        self.attributes.apply(changes, dead_letter);
143	    }
144	
145	    /// Clears the dead-letter configuration if it points at `queue`, which is
146	    /// being deleted.
147	    pub fn detach_dead_letter(&mut self, queue: &str) {
148	        if self
149	            .attributes
150	            .dead_letter
151	            .as_ref()
152	            .is_some_and(|dead_letter| dead_letter.queue == queue)
153	        {
154	            self.attributes.dead_letter = None;
155	        }
156	    }
157	
158	    /// Brings the queue up to `now`: messages past their retention are removed,
159	    /// and messages whose delay or visibility timeout has ended become visible.
160	    /// Every command that reads the queue calls this first.
161	    pub fn advance(&mut self, now: u64) {
162	        let retention = u64::from(self.attributes.retention_seconds);
163	        if let Some(threshold) = now.checked_sub(retention) {
164	            // Expired means `now >= sent_at + retention`, that is `sent_at <= threshold`.
165	            while let Some(&(sent_at, key)) = self.by_sent.first() {
166	                if sent_at > threshold {
167	                    break;
168	                }
169	                self.remove(now, key);
170	            }
171	        }
172	        while let Some(&(visible_at, key)) = self.waking.first() {
173	            if visible_at > now {
174	                break;
175	            }
176	            self.waking.pop_first();
177	            self.make_ready_if_head(key);
178	        }
179	    }
180	
181	    pub fn counts(&self, now: u64) -> Counts {
182	        let mut counts = Counts::default();
183	        for message in self.messages.values() {
184	            match message.state(now) {
185	                State::Delayed => counts.delayed += 1,
186	                State::InFlight => counts.in_flight += 1,
187	                State::Visible => counts.visible += 1,
188	            }
189	        }
190	        counts
191	    }
192	
193	    pub fn purge(&mut self) {
194	        // Sequence numbers and deduplication records outlive the messages.
195	        self.messages.clear();
196	        self.by_sent.clear();
197	        self.waking.clear();
198	        self.ready.clear();
199	        self.groups.clear();
200	        self.receipts.clear();
201	    }
202	
203	    /// The rules of SendMessage that depend on the queue's type (section 6,
204	    /// rules 1 to 3).
205	    pub fn check_send(&self, request: &SendRequest) -> Result<(), Error> {
206	        if !self.attributes.fifo {
207	            if request.group_id.is_some() || request.deduplication_id.is_some() {
208	                return Err(Error::new(
209	                    ErrorCode::UnsupportedOperation,
210	                    "GroupId and DeduplicationId are only allowed on a FIFO queue",
211	                ));
212	            }
213	            return Ok(());
214	        }
215	        if request.delay_seconds.is_some() {
216	            return Err(Error::new(
217	                ErrorCode::UnsupportedOperation,
218	                "DelaySeconds is not allowed on a FIFO queue",
219	            ));
220	        }
221	        if request.group_id.is_none() {
222	            return Err(Error::new(
223	                ErrorCode::MissingParameter,
224	                "GroupId is required on a FIFO queue",
225	            ));
226	        }
227	        if request.deduplication_id.is_none() && !self.attributes.content_based_deduplication {
228	            return Err(Error::new(
229	                ErrorCode::MissingParameter,
230	                "DeduplicationId is required when ContentBasedDeduplication is false",
231	            ));
232	        }
233	        Ok(())
234	    }
235	
236	    /// The earlier FIFO send that makes `request` a duplicate, as the
237	    /// `(message id, sequence number)` it was accepted with.
238	    pub fn duplicate_of(&self, now: u64, request: &SendRequest) -> Option<(u64, u64)> {
239	        if !self.attributes.fifo {
240	            return None;
241	        }
242	        self.deduplication
243	            .get(deduplication_id(request))
244	            .filter(|accepted| now < accepted.at.saturating_add(DEDUPLICATION_WINDOW))
245	            .map(|accepted| (accepted.message_id, accepted.sequence_number))
246	    }
247	
248	    /// Rule 5 of SendMessage: the queue must have room for one more message.
249	    pub fn check_capacity(&self) -> Result<(), Error> {
250	        if self.messages.len() >= MAX_MESSAGES {
251	            return Err(Error::new(
252	                ErrorCode::LimitExceeded,
253	                format!("a queue holds at most {MAX_MESSAGES} messages"),
254	            ));
255	        }
256	        Ok(())
257	    }
258	
259	    /// Adds an accepted message at the end of the queue. Returns its sequence
260	    /// number on a FIFO queue.
261	    pub fn push(&mut self, now: u64, message_id: u64, request: SendRequest) -> Option<u64> {
262	        let delay = request
263	            .delay_seconds
264	            .unwrap_or(self.attributes.delay_seconds);
265	        let sequence_number = if self.attributes.fifo {
266	            let number = self.take_sequence();
267	            self.deduplication.insert(
268	                deduplication_id(&request).to_owned(),
269	                Accepted {
270	                    at: now,
271	                    message_id,
272	                    sequence_number: number,
273	                },
274	            );
275	            Some(number)
276	        } else {
277	            None
278	        };
279	        self.insert(
280	            now,
281	            Message {
282	                id: message_id,
283	                body: request.body,
284	                group_id: request.group_id,
285	                sequence_number,
286	                sent_at: now,
287	                receive_count: 0,
288	                first_received_at: None,
289	                visible_at: now.saturating_add(u64::from(delay)),
290	                latest_receipt: None,
291	            },
292	        );
293	        sequence_number
294	    }
295	
296	    /// Adds a message moved from a source queue to the end of this queue, which
297	    /// is its dead-letter queue. It keeps its id, body, sent time and group, and
298	    /// starts again: no receives, visible at once, no receipt. A FIFO queue gives
299	    /// it the next sequence number, and a message already past this queue's
300	    /// retention is dropped on arrival.
301	    pub fn accept_dead_letter(&mut self, now: u64, mut message: Message) {
302	        let sequence_number = self.attributes.fifo.then(|| self.take_sequence());
303	        if expired(now, message.sent_at, self.attributes.retention_seconds) {
304	            return;
305	        }
306	        message.receive_count = 0;
307	        message.first_received_at = None;
308	        message.visible_at = now;
309	        message.latest_receipt = None;
310	        message.sequence_number = sequence_number;
311	        self.insert(now, message);
312	    }
313	
314	    /// Runs ReceiveMessage (section 6): delivers up to `max` ready messages in
315	    /// arrival order, and moves messages that have used up their receives out
316	    /// of this queue. Each delivery takes the next receipt number from
317	    /// `next_receipt`.
318	    ///
319	    /// Moved messages do not count toward `max`. Moving one can make the next
320	    /// message of its FIFO group the group's first, so the scan keeps its place
321	    /// by arrival and picks that message up if it comes later.
322	    pub fn receive(
323	        &mut self,
324	        now: u64,
325	        max: u32,
326	        visibility_timeout: u32,
327	        next_receipt: &mut u64,
328	    ) -> ReceiveOutcome {
329	        let mut outcome = ReceiveOutcome::default();
330	        let mut delivered = 0;
331	        let mut cursor = 0;
332	        while delivered < max {
333	            let Some(key) = self.ready.range(cursor..).next().copied() else {
334	                break;
335	            };
336	            cursor = key + 1;
337	            if self.exhausted(key) {
338	                let message = self
339	                    .remove(now, key)
340	                    .expect("ready arrivals name stored messages");
341	                outcome.dead_letters.push(message);
342	            } else {
343	                outcome
344	                    .deliveries
345	                    .push(self.deliver(now, key, visibility_timeout, next_receipt));
346	                delivered += 1;
347	            }
348	        }
349	        outcome
350	    }
351	
352	    /// Deletes the message that `receipt` is the latest handle of. The handle
353	    /// must still be in flight at `now`.
354	    pub fn delete_message(&mut self, now: u64, receipt: u64) -> Result<(), Error> {
355	        let key = self
356	            .in_flight_key(now, receipt)
357	            .ok_or_else(receipt_expired)?;
358	        self.remove(now, key);
359	        Ok(())
360	    }
361	
362	    /// Ends the visibility timeout of the message `receipt` is the latest
363	    /// handle of, `visibility_timeout` seconds from `now`.
364	    pub fn change_visibility(
365	        &mut self,
366	        now: u64,
367	        receipt: u64,
368	        visibility_timeout: u32,
369	    ) -> Result<(), Error> {
370	        let key = self
371	            .in_flight_key(now, receipt)
372	            .ok_or_else(receipt_expired)?;
373	        let visible_at = now.saturating_add(u64::from(visibility_timeout));
374	        let previous = {
375	            let message = self
376	                .messages
377	                .get_mut(&key)
378	                .expect("in-flight keys name stored messages");
379	            std::mem::replace(&mut message.visible_at, visible_at)
380	        };
381	        self.waking.remove(&(previous, key));
382	        self.wake_or_wait(key, visible_at, now);
383	        Ok(())
384	    }
385	
386	    /// Stores a message at the end of the queue and indexes it.
387	    fn insert(&mut self, now: u64, message: Message) {
388	        let key = self.next_arrival;
389	        self.next_arrival += 1;
390	        self.by_sent.insert((message.sent_at, key));
391	        if let Some(group) = &message.group_id {
392	            self.groups.entry(group.clone()).or_default().insert(key);
393	        }
394	        let visible_at = message.visible_at;
395	        self.messages.insert(key, message);
396	        self.wake_or_wait(key, visible_at, now);
397	    }
398	
399	    /// Makes `key` ready if it is visible now, and otherwise schedules its wake-up.
400	    fn wake_or_wait(&mut self, key: u64, visible_at: u64, now: u64) {
401	        if visible_at <= now {
402	            self.make_ready_if_head(key);
403	        } else {
404	            self.waking.insert((visible_at, key));
405	        }
406	    }
407	
408	    /// Makes a visible message ready, unless an earlier message of its FIFO
409	    /// group is still in the queue: then only that earlier message is ready.
410	    fn make_ready_if_head(&mut self, key: u64) {
411	        let message = self
412	            .messages
413	            .get(&key)
414	            .expect("indexed arrivals name stored messages");
415	        let is_head = match &message.group_id {
416	            None => true,
417	            Some(group) => self.groups.get(group).and_then(BTreeSet::first) == Some(&key),
418	        };
419	        if is_head {
420	            self.ready.insert(key);
421	        }
422	    }
423	
424	    /// Removes a message from the queue and from every index. When it was the
425	    /// head of a FIFO group, the group's next message becomes the head.
426	    fn remove(&mut self, now: u64, key: u64) -> Option<Message> {
427	        let message = self.messages.remove(&key)?;
428	        self.by_sent.remove(&(message.sent_at, key));
429	        self.waking.remove(&(message.visible_at, key));
430	        self.ready.remove(&key);
431	        if let Some(group) = &message.group_id {
432	            let (next_head, now_empty) = match self.groups.get_mut(group) {
433	                Some(members) => {
434	                    members.remove(&key);
435	                    (members.first().copied(), members.is_empty())
436	                }
437	                None => (None, true),
438	            };
439	            if now_empty {
440	                self.groups.remove(group);
441	            }
442	            if let Some(head) = next_head {
443	                let visible = self
444	                    .messages
445	                    .get(&head)
446	                    .is_some_and(|next| now >= next.visible_at);
447	                if visible {
448	                    self.make_ready_if_head(head);
449	                }
450	            }
451	        }
452	        Some(message)
453	    }
454	
455	    /// Whether a receive would move this message to the dead-letter queue.
456	    fn exhausted(&self, key: u64) -> bool {
457	        let message = self
458	            .messages
459	            .get(&key)
460	            .expect("ready arrivals name stored messages");
461	        self.attributes
462	            .dead_letter
463	            .as_ref()
464	            .is_some_and(|dead_letter| message.receive_count >= dead_letter.max_receive_count)
465	    }
466	
467	    /// Delivers the ready message at `key`, which stays in the queue in flight.
468	    fn deliver(
469	        &mut self,
470	        now: u64,
471	        key: u64,
472	        visibility_timeout: u32,
473	        next_receipt: &mut u64,
474	    ) -> Delivery {
475	        let receipt = *next_receipt;
476	        *next_receipt += 1;
477	        self.ready.remove(&key);
478	        let visible_at = now.saturating_add(u64::from(visibility_timeout));
479	        let message = self
480	            .messages
481	            .get_mut(&key)
482	            .expect("ready arrivals name stored messages");
483	        message.receive_count += 1;
484	        let first_received_at = *message.first_received_at.get_or_insert(now);
485	        message.visible_at = visible_at;
486	        message.latest_receipt = Some(receipt);
487	        let delivery = Delivery {
488	            message_id: message.id,
489	            receipt,
490	            body: message.body.clone(),
491	            receive_count: message.receive_count,
492	            sent_at: message.sent_at,
493	            first_received_at,
494	            group_id: message.group_id.clone(),
495	            sequence_number: message.sequence_number,
496	        };
497	        self.receipts.insert(receipt, key);
498	        self.wake_or_wait(key, visible_at, now);
499	        delivery
500	    }
501	
502	    /// The arrival of the message `receipt` is the latest handle of, if that
503	    /// message is in flight at `now`.
504	    fn in_flight_key(&self, now: u64, receipt: u64) -> Option<u64> {
505	        let key = *self.receipts.get(&receipt)?;
506	        let message = self.messages.get(&key)?;
507	        (message.latest_receipt == Some(receipt) && message.state(now) == State::InFlight)
508	            .then_some(key)
509	    }
510	
511	    fn take_sequence(&mut self) -> u64 {
512	        let number = self.next_sequence;
513	        self.next_sequence += 1;
514	        number
515	    }
516	}
517	
518	/// The deduplication id of a FIFO send: its own id, or the body when the
519	/// queue derives ids from content.
520	fn deduplication_id(request: &SendRequest) -> &str {
521	    request.deduplication_id.as_deref().unwrap_or(&request.body)
522	}
523	
524	/// Whether a message sent at `sent_at` is past its retention by `now`.
525	fn expired(now: u64, sent_at: u64, retention_seconds: u32) -> bool {
526	    now >= sent_at.saturating_add(u64::from(retention_seconds))
527	}
528	
529	fn receipt_expired() -> Error {
530	    Error::new(
531	        ErrorCode::ReceiptHandleExpired,
532	        "the receipt handle is no longer the latest one of an in-flight message",
533	    )
534	}
