1	//! Turns a parsed command object into a typed `Command`.
2	//!
3	//! Covers steps 1 to 3 of SPEC.md section 2: the command name, the presence of
4	//! required parameters, then each parameter's type and range. Checks that need
5	//! queue state happen later, in the broker.
6	
7	use std::ops::RangeInclusive;
8	
9	use serde_json::{Map, Value};
10	
11	use crate::attributes::AttributeChanges;
12	use crate::{Error, ErrorCode};
13	
14	#[derive(Debug, PartialEq, Eq)]
15	pub enum Command {
16	    CreateQueue {
17	        name: String,
18	        attributes: AttributeChanges,
19	    },
20	    SetQueueAttributes {
21	        name: String,
22	        changes: AttributeChanges,
23	    },
24	    GetQueueAttributes {
25	        name: String,
26	    },
27	    ListQueues {
28	        prefix: Option<String>,
29	    },
30	    DeleteQueue {
31	        name: String,
32	    },
33	    PurgeQueue {
34	        name: String,
35	    },
36	    Tick {
37	        seconds: u32,
38	    },
39	    SendMessage(SendRequest),
40	    ReceiveMessage(ReceiveRequest),
41	    DeleteMessage {
42	        queue: String,
43	        receipt: String,
44	    },
45	    ChangeMessageVisibility {
46	        queue: String,
47	        receipt: String,
48	        visibility_timeout: u32,
49	    },
50	}
51	
52	#[derive(Debug, PartialEq, Eq)]
53	pub struct SendRequest {
54	    pub queue: String,
55	    pub body: String,
56	    pub delay_seconds: Option<u32>,
57	    pub group_id: Option<String>,
58	    pub deduplication_id: Option<String>,
59	}
60	
61	#[derive(Debug, PartialEq, Eq)]
62	pub struct ReceiveRequest {
63	    pub queue: String,
64	    pub max_messages: u32,
65	    pub visibility_timeout: Option<u32>,
66	}
67	
68	pub fn parse(object: &Map<String, Value>) -> Result<Command, Error> {
69	    let Some(Value::String(command)) = object.get("Command") else {
70	        return Err(invalid_request("missing string Command member"));
71	    };
72	    match command.as_str() {
73	        "CreateQueue" => create_queue(object),
74	        "SetQueueAttributes" => set_queue_attributes(object),
75	        "GetQueueAttributes" => Ok(Command::GetQueueAttributes {
76	            name: queue_name(object)?,
77	        }),
78	        "ListQueues" => list_queues(object),
79	        "DeleteQueue" => Ok(Command::DeleteQueue {
80	            name: queue_name(object)?,
81	        }),
82	        "PurgeQueue" => Ok(Command::PurgeQueue {
83	            name: queue_name(object)?,
84	        }),
85	        "Tick" => tick(object),
86	        "SendMessage" => send_message(object),
87	        "ReceiveMessage" => receive_message(object),
88	        "DeleteMessage" => {
89	            let (queue, receipt) = queue_and_receipt(object)?;
90	            Ok(Command::DeleteMessage { queue, receipt })
91	        }
92	        "ChangeMessageVisibility" => change_message_visibility(object),
93	        other => Err(invalid_request(format!("unknown command {other}"))),
94	    }
95	}
96	
97	fn change_message_visibility(object: &Map<String, Value>) -> Result<Command, Error> {
98	    let queue = required(object, "QueueName")?;
99	    let receipt = required(object, "ReceiptHandle")?;
100	    let visibility = required(object, "VisibilityTimeout")?;
101	    Ok(Command::ChangeMessageVisibility {
102	        queue: as_string("QueueName", queue)?.to_owned(),
103	        receipt: as_string("ReceiptHandle", receipt)?.to_owned(),
104	        visibility_timeout: integer("VisibilityTimeout", visibility, 0..=43_200)?,
105	    })
106	}
107	
108	/// The QueueName and ReceiptHandle of a message command.
109	fn queue_and_receipt(object: &Map<String, Value>) -> Result<(String, String), Error> {
110	    let queue = required(object, "QueueName")?;
111	    let receipt = required(object, "ReceiptHandle")?;
112	    Ok((
113	        as_string("QueueName", queue)?.to_owned(),
114	        as_string("ReceiptHandle", receipt)?.to_owned(),
115	    ))
116	}
117	
118	fn send_message(object: &Map<String, Value>) -> Result<Command, Error> {
119	    let queue = required(object, "QueueName")?;
120	    let body = required(object, "Body")?;
121	    let body = as_string("Body", body)?;
122	    if !(1..=1024).contains(&body.len()) {
123	        return Err(invalid_value("Body", "must be 1 to 1024 bytes"));
124	    }
125	    let delay_seconds = optional(object, "DelaySeconds")
126	        .map(|value| integer("DelaySeconds", value, 0..=900))
127	        .transpose()?;
128	    let group_id = optional(object, "GroupId")
129	        .map(|value| identifier("GroupId", value))
130	        .transpose()?;
131	    let deduplication_id = optional(object, "DeduplicationId")
132	        .map(|value| identifier("DeduplicationId", value))
133	        .transpose()?;
134	    Ok(Command::SendMessage(SendRequest {
135	        queue: as_string("QueueName", queue)?.to_owned(),
136	        body: body.to_owned(),
137	        delay_seconds,
138	        group_id,
139	        deduplication_id,
140	    }))
141	}
142	
143	fn receive_message(object: &Map<String, Value>) -> Result<Command, Error> {
144	    let queue = queue_name(object)?;
145	    let max_messages = optional(object, "MaxMessages")
146	        .map(|value| integer("MaxMessages", value, 1..=10))
147	        .transpose()?
148	        .unwrap_or(1);
149	    let visibility_timeout = optional(object, "VisibilityTimeout")
150	        .map(|value| integer("VisibilityTimeout", value, 0..=43_200))
151	        .transpose()?;
152	    Ok(Command::ReceiveMessage(ReceiveRequest {
153	        queue,
154	        max_messages,
155	        visibility_timeout,
156	    }))
157	}
158	
159	fn create_queue(object: &Map<String, Value>) -> Result<Command, Error> {
160	    // QueueName is checked before any other parameter (SPEC.md section 2, step 3).
161	    let name = as_string("QueueName", required(object, "QueueName")?)?;
162	    if !is_valid_queue_name(name) {
163	        return Err(Error::new(
164	            ErrorCode::QueueNameInvalid,
165	            "a queue name is 1 to 80 characters of A-Z a-z 0-9 _ -, or 1 to 75 of those followed by .fifo",
166	        ));
167	    }
168	    let attributes = match optional(object, "Attributes") {
169	        Some(value) => attribute_changes(value)?,
170	        None => AttributeChanges::default(),
171	    };
172	    Ok(Command::CreateQueue {
173	        name: name.to_owned(),
174	        attributes,
175	    })
176	}
177	
178	fn set_queue_attributes(object: &Map<String, Value>) -> Result<Command, Error> {
179	    let name = required(object, "QueueName")?;
180	    let attributes = required(object, "Attributes")?;
181	    Ok(Command::SetQueueAttributes {
182	        name: as_string("QueueName", name)?.to_owned(),
183	        changes: attribute_changes(attributes)?,
184	    })
185	}
186	
187	fn list_queues(object: &Map<String, Value>) -> Result<Command, Error> {
188	    let prefix = optional(object, "Prefix")
189	        .map(|value| as_string("Prefix", value).map(str::to_owned))
190	        .transpose()?;
191	    Ok(Command::ListQueues { prefix })
192	}
193	
194	fn tick(object: &Map<String, Value>) -> Result<Command, Error> {
195	    let seconds = integer("Seconds", required(object, "Seconds")?, 0..=1_209_600)?;
196	    Ok(Command::Tick { seconds })
197	}
198	
199	/// Parses an `Attributes` object. A member that is `null` counts as absent.
200	fn attribute_changes(value: &Value) -> Result<AttributeChanges, Error> {
201	    let Value::Object(members) = value else {
202	        return Err(invalid_value("Attributes", "must be an object"));
203	    };
204	    let mut changes = AttributeChanges::default();
205	    for (name, value) in members.iter().filter(|(_, value)| !value.is_null()) {
206	        match name.as_str() {
207	            "VisibilityTimeout" => {
208	                changes.visibility_timeout = Some(integer(name, value, 0..=43_200)?);
209	            }
210	            "DelaySeconds" => changes.delay_seconds = Some(integer(name, value, 0..=900)?),
211	            "RetentionSeconds" => {
212	                changes.retention_seconds = Some(integer(name, value, 60..=1_209_600)?);
213	            }
214	            "Fifo" => changes.fifo = Some(boolean(name, value)?),
215	            "ContentBasedDeduplication" => {
216	                changes.content_based_deduplication = Some(boolean(name, value)?);
217	            }
218	            "DeadLetterQueue" => {
219	                changes.dead_letter_queue = Some(as_string(name, value)?.to_owned());
220	            }
221	            "MaxReceiveCount" => changes.max_receive_count = Some(integer(name, value, 1..=1_000)?),
222	            _ => return Err(invalid_value(name, "is not a queue attribute")),
223	        }
224	    }
225	    Ok(changes)
226	}
227	
228	fn queue_name(object: &Map<String, Value>) -> Result<String, Error> {
229	    Ok(as_string("QueueName", required(object, "QueueName")?)?.to_owned())
230	}
231	
232	/// A required parameter: absent and `null` both count as missing.
233	fn required<'a>(object: &'a Map<String, Value>, name: &str) -> Result<&'a Value, Error> {
234	    optional(object, name)
235	        .ok_or_else(|| Error::new(ErrorCode::MissingParameter, format!("{name} is required")))
236	}
237	
238	/// An optional parameter: absent and `null` both count as not given.
239	fn optional<'a>(object: &'a Map<String, Value>, name: &str) -> Option<&'a Value> {
240	    object.get(name).filter(|value| !value.is_null())
241	}
242	
243	fn as_string<'a>(name: &str, value: &'a Value) -> Result<&'a str, Error> {
244	    value
245	        .as_str()
246	        .ok_or_else(|| invalid_value(name, "must be a string"))
247	}
248	
249	/// A GroupId or DeduplicationId: 1 to 128 characters of `A-Z a-z 0-9 _ -`.
250	fn identifier(name: &str, value: &Value) -> Result<String, Error> {
251	    let text = as_string(name, value)?;
252	    let valid = (1..=128).contains(&text.len())
253	        && text
254	            .bytes()
255	            .all(|byte| byte.is_ascii_alphanumeric() || byte == b'_' || byte == b'-');
256	    if !valid {
257	        return Err(invalid_value(
258	            name,
259	            "must be 1 to 128 characters of A-Z a-z 0-9 _ -",
260	        ));
261	    }
262	    Ok(text.to_owned())
263	}
264	
265	fn boolean(name: &str, value: &Value) -> Result<bool, Error> {
266	    value
267	        .as_bool()
268	        .ok_or_else(|| invalid_value(name, "must be true or false"))
269	}
270	
271	/// A JSON integer in `range`. Numbers written with a fraction or exponent,
272	/// such as `30.0` or `3e1`, are not integers and are rejected.
273	fn integer(name: &str, value: &Value, range: RangeInclusive<u32>) -> Result<u32, Error> {
274	    value
275	        .as_u64()
276	        .and_then(|number| u32::try_from(number).ok())
277	        .filter(|number| range.contains(number))
278	        .ok_or_else(|| {
279	            invalid_value(
280	                name,
281	                &format!(
282	                    "must be an integer from {} to {}",
283	                    range.start(),
284	                    range.end()
285	                ),
286	            )
287	        })
288	}
289	
290	/// A queue name: 1 to 80 characters of `A-Z a-z 0-9 _ -`, or 1 to 75 of those
291	/// followed by `.fifo`.
292	fn is_valid_queue_name(name: &str) -> bool {
293	    let (base, max_len) = match name.strip_suffix(".fifo") {
294	        Some(base) => (base, 75),
295	        None => (name, 80),
296	    };
297	    (1..=max_len).contains(&base.len())
298	        && base
299	            .bytes()
300	            .all(|byte| byte.is_ascii_alphanumeric() || byte == b'_' || byte == b'-')
301	}
302	
303	fn invalid_request(message: impl Into<String>) -> Error {
304	    Error::new(ErrorCode::InvalidRequest, message)
305	}
306	
307	fn invalid_value(name: &str, expectation: &str) -> Error {
308	    Error::new(
309	        ErrorCode::InvalidParameterValue,
310	        format!("{name} {expectation}"),
311	    )
312	}
