1	//! Queue attributes and the request forms that set them (SPEC.md section 4).
2	
3	use crate::{Error, ErrorCode};
4	
5	/// The configuration of one queue, with defaults already applied.
6	#[derive(Debug, Clone, PartialEq, Eq)]
7	pub struct Attributes {
8	    pub visibility_timeout: u32,
9	    pub delay_seconds: u32,
10	    pub retention_seconds: u32,
11	    pub fifo: bool,
12	    pub content_based_deduplication: bool,
13	    /// Both dead-letter members are set or both are unset, so they share one option.
14	    pub dead_letter: Option<DeadLetter>,
15	}
16	
17	#[derive(Debug, Clone, PartialEq, Eq)]
18	pub struct DeadLetter {
19	    pub queue: String,
20	    pub max_receive_count: u32,
21	}
22	
23	impl Default for Attributes {
24	    fn default() -> Self {
25	        Attributes {
26	            visibility_timeout: 30,
27	            delay_seconds: 0,
28	            retention_seconds: 345_600,
29	            fifo: false,
30	            content_based_deduplication: false,
31	            dead_letter: None,
32	        }
33	    }
