35	
36	/// The attributes a request gives. `None` means the request did not set it,
37	/// which is different from setting it to the default.
38	#[derive(Debug, Clone, Default, PartialEq, Eq)]
39	pub struct AttributeChanges {
40	    pub visibility_timeout: Option<u32>,
41	    pub delay_seconds: Option<u32>,
42	    pub retention_seconds: Option<u32>,
43	    pub fifo: Option<bool>,
44	    pub content_based_deduplication: Option<bool>,
45	    pub dead_letter_queue: Option<String>,
46	    pub max_receive_count: Option<u32>,
47	}
48	
49	impl AttributeChanges {
50	    /// The dead-letter configuration the request gives: `None` when neither
51	    /// member is present, an error when only one of them is.
52	    pub fn dead_letter(&self) -> Result<Option<DeadLetter>, Error> {
53	        match (&self.dead_letter_queue, self.max_receive_count) {
54	            (None, None) => Ok(None),
55	            (Some(queue), Some(max_receive_count)) => Ok(Some(DeadLetter {
56	                queue: queue.clone(),
57	                max_receive_count,
58	            })),
59	            _ => Err(Error::new(
60	                ErrorCode::InvalidParameterValue,
61	                "DeadLetterQueue and MaxReceiveCount must be given together",
62	            )),
63	        }
64	    }
65	}
