1	//! Line framing and response rendering (SPEC.md section 1).
2	
3	use std::io::{self, BufRead, Write};
4	
5	use serde_json::{json, Map, Value};
6	
7	use crate::attributes::Attributes;
8	use crate::broker::{Broker, Reply};
9	use crate::command;
10	use crate::queue::Delivery;
11	use crate::{Error, ErrorCode};
12	
13	/// Reads commands line by line from `input` and writes one response line per
14	/// command to `output`, flushing each response before reading the next line.
15	///
16	/// Returns `Ok(())` at end of input. Errors are only I/O failures; a bad
17	/// command gets an `ok: false` response instead.
18	pub fn serve<R: BufRead, W: Write>(mut input: R, mut output: W) -> io::Result<()> {
19	    let mut broker = Broker::new();
20	    let mut line = Vec::new();
21	    loop {
22	        line.clear();
23	        if input.read_until(b'\n', &mut line)? == 0 {
24	            return Ok(());
25	        }
26	        if line.last() == Some(&b'\n') {
27	            line.pop();
28	        }
29	        let response = render(handle_line(&mut broker, &line));
30	        serde_json::to_writer(&mut output, &response)?;
31	        output.write_all(b"\n")?;
32	        output.flush()?;
33	    }
34	}
35	
36	fn handle_line(broker: &mut Broker, line: &[u8]) -> Result<Reply, Error> {
37	    let text = std::str::from_utf8(line)
38	        .map_err(|_| Error::new(ErrorCode::InvalidRequest, "line is not valid UTF-8"))?;
39	    let value: Value = serde_json::from_str(text).map_err(|err| {
40	        Error::new(
41	            ErrorCode::InvalidRequest,
42	            format!("line is not JSON: {err}"),
43	        )
44	    })?;
45	    let Value::Object(object) = value else {
46	        return Err(Error::new(
47	            ErrorCode::InvalidRequest,
48	            "line is not a JSON object",
49	        ));
50	    };
51	    broker.execute(command::parse(&object)?)
52	}
53	
54	fn render(outcome: Result<Reply, Error>) -> Value {
55	    match outcome {
56	        Ok(reply) => {
57	            let mut members = Map::new();
58	            members.insert("ok".to_owned(), Value::Bool(true));
59	            members.extend(reply_members(reply));
60	            Value::Object(members)
61	        }
62	        Err(error) => json!({
63	            "ok": false,
64	            "error": {"code": error.code.as_str(), "message": error.message},
65	        }),
66	    }
67	}
68	
69	fn reply_members(reply: Reply) -> Map<String, Value> {
70	    let mut members = Map::new();
71	    match reply {
72	        Reply::Empty => {}
73	        Reply::QueueAttributes { attributes, counts } => {
74	            members.insert("Attributes".to_owned(), attributes_json(&attributes));
75	            members.insert(
76	                "Counts".to_owned(),
77	                json!({
78	                    "Visible": counts.visible,
79	                    "InFlight": counts.in_flight,
80	                    "Delayed": counts.delayed,
81	                }),
82	            );
83	        }
84	        Reply::QueueNames(names) => {
85	            members.insert("QueueNames".to_owned(), json!(names));
86	        }
87	        Reply::Now(now) => {
88	            members.insert("Now".to_owned(), json!(now));
89	        }
90	        Reply::Sent {
91	            message_id,
92	            sequence_number,
93	        } => {
94	            members.insert("MessageId".to_owned(), json!(format!("m-{message_id}")));
95	            if let Some(sequence_number) = sequence_number {
96	                members.insert("SequenceNumber".to_owned(), json!(sequence_number));
97	            }
98	        }
99	        Reply::Received(deliveries) => {
100	            let messages: Vec<Value> = deliveries.iter().map(delivery_json).collect();
101	            members.insert("Messages".to_owned(), Value::Array(messages));
102	        }
103	    }
104	    members
105	}
106	
107	fn delivery_json(delivery: &Delivery) -> Value {
108	    let mut message = Map::new();
109	    message.insert(
110	        "MessageId".to_owned(),
111	        json!(format!("m-{}", delivery.message_id)),
112	    );
113	    message.insert(
114	        "ReceiptHandle".to_owned(),
115	        json!(format!("r-{}", delivery.receipt)),
116	    );
117	    message.insert("Body".to_owned(), json!(delivery.body));
118	    message.insert("ReceiveCount".to_owned(), json!(delivery.receive_count));
119	    message.insert("SentAt".to_owned(), json!(delivery.sent_at));
120	    message.insert(
121	        "FirstReceivedAt".to_owned(),
122	        json!(delivery.first_received_at),
123	    );
124	    if let Some(group_id) = &delivery.group_id {
125	        message.insert("GroupId".to_owned(), json!(group_id));
126	    }
127	    if let Some(sequence_number) = delivery.sequence_number {
128	        message.insert("SequenceNumber".to_owned(), json!(sequence_number));
129	    }
130	    Value::Object(message)
131	}
132	
133	fn attributes_json(attributes: &Attributes) -> Value {
134	    let mut members = Map::new();
135	    members.insert(
136	        "VisibilityTimeout".to_owned(),
137	        json!(attributes.visibility_timeout),
138	    );
139	    members.insert("DelaySeconds".to_owned(), json!(attributes.delay_seconds));
140	    members.insert(
141	        "RetentionSeconds".to_owned(),
142	        json!(attributes.retention_seconds),
143	    );
144	    members.insert("Fifo".to_owned(), json!(attributes.fifo));
145	    members.insert(
146	        "ContentBasedDeduplication".to_owned(),
147	        json!(attributes.content_based_deduplication),
148	    );
149	    if let Some(dead_letter) = &attributes.dead_letter {
150	        members.insert("DeadLetterQueue".to_owned(), json!(dead_letter.queue));
151	        members.insert(
152	            "MaxReceiveCount".to_owned(),
153	            json!(dead_letter.max_receive_count),
154	        );
155	    }
156	    Value::Object(members)
157	}
